    if(a==='gov-version'){const p=state.posts.find(p=>p.id===el.dataset.post);assert(state,ui,'read',p);const v=p.versions.find(v=>v.id===el.dataset.version);if(!v)fail('The version is unavailable.');ctx.showModal('Historical creative · V'+v.number,'<div class="modal-body"><p>'+e(v.state)+' · Brief '+v.briefRevision+' · '+e(v.createdAt)+'</p><p class="governance-caption">'+e(v.caption)+'</p>'+v.assets.map((asset,i)=>'<figure>'+(asset.type==='video'?'<video controls src="'+e(root.JMLStorage?.mediaURL(asset.url)||asset.url)+'"></video>':'<img style="max-width:100%" src="'+e(root.JMLStorage?.mediaURL(asset.url)||asset.url)+'" alt="'+e(asset.alt||asset.name)+'">')+'<figcaption>'+e((i+1)+'. '+asset.name)+'</figcaption></figure>').join('')+'<p>Read-only historical package. Decisions apply only to the current assigned version.</p></div>');return true;}
    if(a==='gov-stage'){assert(state,ui,'admin');const stage=Number(el.dataset.stage),def=stages[stage-1],saved=state.governance.stageAssignments?.find(x=>x.brandId===ui.brand&&x.stage===stage);if(!def)fail('Choose a workflow stage.');const picker=(type,fn)=>'<label>'+type+' owner<select name="'+type+'PersonId">'+eligiblePeople(state,ui.brand,fn).map(p=>'<option value="'+e(p.id)+'" '+(saved?.[type+'PersonId']===p.id?'selected':'')+'>'+e(p.name)+'</option>').join('')+'</select></label>';formModal(def[0]+' ownership','governance-stage',picker('delivery',def[1])+picker('decision',def[2]),'Save stage owners','data-stage="'+stage+'"');return true;}
    if(a==='gov-new-member'||a==='gov-edit-member'){assert(state,ui,'admin');const m=state.governance.memberships.find(m=>m.id===el.dataset.id)||{};formModal('Account membership','governance-member','<label>Person<select name="personId">'+state.governance.people.filter(p=>p.active!==false&&!p.agencyAdmin).map(p=>'<option value="'+e(p.id)+'" '+(m.personId===p.id?'selected':'')+'>'+e(p.name)+'</option>').join('')+'</select></label><label>Access preset<select name="preset">'+Object.entries(presets).filter(([k])=>k!=='agency-admin').map(([k,v])=>'<option value="'+k+'" '+(m.preset===k?'selected':'')+'>'+v+'</option>').join('')+'</select></label><fieldset><legend>Workflow functions</legend>'+Object.entries(functions).map(([k,v])=>'<label class="check-inline"><input type="checkbox" name="functions" value="'+k+'" '+(m.functions?.includes(k)?'checked':'')+'>'+e(v)+'</label>').join('')+'</fieldset><label class="check-inline"><input type="checkbox" name="shared" '+(m.shareClientMaterial?'checked':'')+'>Share submitted client material and reports</label><label class="check-inline"><input type="checkbox" name="active" '+(m.active!==false?'checked':'')+'>Active membership</label>','Save membership','data-id="'+e(m.id||'')+'"');return true;}
    if(a==='gov-assign'){const p=state.posts.find(p=>p.id===el.dataset.post);assert(state,ui,'coordinate',p);formModal('Assign a versioned handoff','governance-assignment','<label>Responsibility<select name="kind">'+Object.keys(assignmentFunctions).map(k=>'<option>'+k+'</option>').join('')+'</select></label><label>Recipient<select name="personId">'+eligiblePeople(state,p.brandId).map(p=>'<option value="'+e(p.id)+'">'+e(p.name)+'</option>').join('')+'</select></label>'+input('Due date','due',p.date||'','date')+input('Handoff or reassignment reason','reason'),'Assign work','data-post="'+e(p.id)+'"');return true;}
    if(a==='gov-open'){const n=state.governance.notifications.find(n=>n.id===el.dataset.id&&n.recipientId===ui.personId&&n.brandId===ui.brand);if(!n)fail('This notification is not available.');await ctx.commit(next=>{next.governance.notifications.find(x=>x.id===n.id).readAt=C.now();},'',{render:false});const assignment=state.governance.assignments.find(a=>a.id===n.assignmentId),p=state.posts.find(p=>p.id===n.contentId),v=p?.versions.find(v=>v.id===n.versionId),stale=!p||p.briefRevision!==n.briefRevision||n.versionId&&C.latest(p)?.id!==n.versionId||assignment?.state==='superseded';ctx.showModal('Assigned work · '+e(p?.title||n.contentId),'<div class="governance-panel"><p>'+e(assignment?.kind)+' · Brief '+n.briefRevision+' · '+(v?'Creative V'+v.number:'No creative yet')+'</p><p>'+e(assignment?.reason||'')+'</p>'+(v?'<p class="governance-caption">'+e(v.caption)+'</p>':'')+(stale?'<p class="notice warning">This handoff is superseded. It remains available for history; new decisions require the current assignment.</p>':'<label>Response note<textarea id="gov-response-note"></textarea></label>')+'</div>',(stale?'':btn('Accept','gov-response','','data-id="'+e(assignment.id)+'" data-outcome="accepted"')+' '+btn('Blocked','gov-response','','data-id="'+e(assignment.id)+'" data-outcome="blocked"')+' '+btn('Request reassignment','gov-response','','data-id="'+e(assignment.id)+'" data-outcome="reassignment-requested"'))+assignmentLink(ctx,assignment));return true;}
